```kotlin
interface Repository {
    fun load(): List<Item>
}

class CachingRepository(
    private val origin: Repository,
) : Repository by origin {          // the remaining methods are delegated
    private var cache: List<Item>? = null
    override fun load() = cache ?: origin.load().also { cache = it }
}
